// 座標換算：x = (經度 + 180) × 2.777778，y = (84 − 緯度) × 2.777778
export const MAP_WIDTH = 1000;
export const MAP_HEIGHT = 388.9;
export const MAP_LAT_TOP = 84;
export const MAP_LAT_BOTTOM = -56;
export const MAP_SCALE = 2.7777777777777777;

/** 把經緯度換成地圖畫布上的座標。超出上下範圍的會被夾在邊界上。 */
export function project(lat: number, lon: number): { x: number; y: number } {
	const clampedLat = Math.max(MAP_LAT_BOTTOM, Math.min(MAP_LAT_TOP, lat));
	return {
		x: +(((lon + 180) * MAP_SCALE).toFixed(2)),
		y: +(((MAP_LAT_TOP - clampedLat) * MAP_SCALE).toFixed(2)),
	};
}

